import { User, useAuth } from "@providers/AuthProvider";
import { useState } from "react";
import Image from "next/image";

export default function UsernameSideCard() {

    const [userInfo, setUserInfo] = useState<User | null>(null);

    if (!userInfo) {
        setUserInfo({
            userID: "",
            profilePicture: "/images/profile.png",
            email: "Not Signed In",
            username: "guestuser",
            firstName: "Not",
            lastName: "Signed In",
        });
    }


    return (
        <div className="w-[230px] h-[35px] bg-bg-secondary rounded-[25px] p-4">
            <div className="flex items-center gap-2 w-full h-full">
                <div className="w-[40px] h-[40px] rounded-full overflow-hidden">
                    <Image src={userInfo?.profilePicture && userInfo?.profilePicture.length
                        && userInfo?.profilePicture.length > 0 ? userInfo?.profilePicture
                        : "/images/profile.png"} alt="Profile Picture" width={40} height={40}
                    />
                </div>
                <div className="flex flex-col gap-1">
                    <div className="text-text-primary text-[15px] font-medium capitalize">{userInfo?.firstName} {userInfo?.lastName}</div>
                    <div className="text-text-secondary text-[13px] font-medium lowercase">@{userInfo?.username}</div>
                </div>
            </div>
        </div>
    );
}